import {esc,icon} from './ui.mjs';
import {createDocumentServiceClient,watchDocumentService,fileBase64,documentServiceLoginHref} from './document-services-client.mjs';
const languageNames={zh:'中文',en:'英语'},statusNames={queued:'排队中',pending:'排队中',running:'翻译中',completed:'已完成',failed:'未完成',cancelled:'已取消'},terminal=status=>['completed','failed','cancelled'].includes(status);
export function eligibleTranslationFiles(files){return (Array.isArray(files)?files:[]).filter(file=>file&&typeof file.id==='string'&&/\.(pdf|docx)$/i.test(file.name||'')&&file.deletionStatus!=='pending');}
export function validateTranslationFile(file,cap={}){if(!file||!/\.(pdf|docx)$/i.test(file.name||''))throw Error('请选择 PDF 或 DOCX 文件；旧版 DOC 请先另存为 DOCX。');const max=Math.min(Number(cap.maxFileBytes)||10*1024*1024,/\.docx$/i.test(file.name)?2*1024*1024:10*1024*1024);if(!file.size||file.size>max)throw Error(`${/\.docx$/i.test(file.name)?'DOCX':'PDF'} 文件最大 ${Math.floor(max/1024/1024)}MB，请压缩或拆分后上传。`);return max;}
export function translationDownloadPath(value){if(typeof value!=='string'||!value.startsWith('/api/')||value.startsWith('//')||/[\\\r\n]/.test(value))return '';try{const url=new URL(value,'https://paperknow.cn');return url.origin==='https://paperknow.cn'&&url.pathname.startsWith('/api/artifacts/')&&!url.search?url.pathname:'';}catch{return '';}}
export function mountDocumentTranslation({container,notify=()=>{},fetchImpl,uuid=()=>crypto.randomUUID(),pollInterval=4000}={}){
 let alive=true,session=null,cap={},files=[],jobs=[],selected=null,busy=false,timer=null,unwatch=()=>{},requestKey=uuid(),uploaded=null,operation=0;const $=s=>container.querySelector(s),current=()=>alive&&container.isConnected,client=createDocumentServiceClient({fetchImpl,isCurrent:current});
 const dispose=()=>{if(!alive)return;alive=false;operation++;clearTimeout(timer);client.dispose();unwatch();};unwatch=watchDocumentService(container,dispose);
 const state=(text,error=false)=>{const node=$('[data-doc-translation-status]');if(node){node.textContent=text;node.classList.toggle('is-error',error);}};
 function setBusy(value){busy=value;container.setAttribute('aria-busy',String(value));container.querySelectorAll('[data-doc-translation-form] input,[data-doc-translation-form] select,[data-doc-translation-form] button,[data-doc-translation-refresh],[data-doc-translation-open]').forEach(node=>node.disabled=value);}
 function render(){if(!current())return;container.innerHTML=`<section class="document-service document-translation"><div class="document-service-intro"><span class="document-service-icon">${icon('language',23)}</span><div><h3>翻译整篇文档，保留可编辑的结果</h3><p>中文与英语互译 · PDF / DOCX → Word</p></div></div><p class="document-service-note">尽量保留原文布局；PDF 将译为可编辑 Word。扫描件、复杂表格和公式可能需要进一步核对，不保证与原件逐像素一致。</p><form data-doc-translation-form data-unprotected><div class="document-service-fields"><label>原文语言<select data-doc-source><option value="en">英语</option><option value="zh">中文</option></select></label><label>翻译成<select data-doc-target><option value="zh">中文</option><option value="en">英语</option></select></label></div><label class="document-service-field">选择账户原件<select data-doc-file><option value="">上传新文档</option>${files.map(file=>`<option value="${esc(file.id)}">${esc(file.name)} · ${Math.ceil(Number(file.bytes||0)/1024)} KB</option>`).join('')}</select></label><label class="document-service-upload" data-doc-upload-wrap>${icon('upload',23)}<b>选择 PDF 或 DOCX 原件</b><span>PDF 最大 10MB / ${Math.min(Number(cap.maxPages)||100,100)} 页；DOCX 最大 2MB</span><input type="file" data-doc-upload accept=".pdf,.docx,application/pdf,application/vnd.openxmlformats-officedocument.wordprocessingml.document" aria-label="选择待翻译文档"><small data-doc-upload-name>文件仅在确认提交后上传</small></label><label class="document-service-consent"><input type="checkbox" data-doc-consent><span>我有权处理此文档，并同意将原件保存到我的账户私有存储，再提交阿里云文档翻译服务处理。</span></label><div class="document-service-actions"><button type="submit" class="btn primary">${icon('language',16)} 开始整篇翻译</button><span>当前试用免费，不扣科研积分；每账户每日最多 ${Number(cap.userDailyLimit)||3} 次、${Number(cap.userDailyPages)||100} 页。</span></div></form><p class="document-service-status" data-doc-translation-status role="status" aria-live="polite">请核对原文语言后提交。离开页面不会取消已提交的翻译。</p><section class="document-service-tasks"><header><h3>我的文档翻译</h3><button class="btn secondary" type="button" data-doc-translation-refresh>刷新任务</button></header><div data-doc-translation-jobs></div><div data-doc-translation-detail></div></section></section>`;renderJobs();
 $('[data-doc-file]').onchange=()=>{$('[data-doc-upload-wrap]').hidden=!!$('[data-doc-file]').value;uploaded=null;requestKey=uuid();};$('[data-doc-upload]').onchange=()=>{const file=$('[data-doc-upload]').files?.[0];$('[data-doc-upload-name]').textContent=file?file.name:'文件仅在确认提交后上传';uploaded=null;requestKey=uuid();};$('[data-doc-source]').onchange=()=>{$('[data-doc-target]').value=$('[data-doc-source]').value==='en'?'zh':'en';requestKey=uuid();};$('[data-doc-target]').onchange=()=>{requestKey=uuid();};$('[data-doc-translation-form]').onsubmit=event=>{event.preventDefault();void submit();};$('[data-doc-translation-refresh]').onclick=()=>void refresh();
 }
 function renderJobs(){if(!current())return;const node=$('[data-doc-translation-jobs]');if(!node)return;node.innerHTML=jobs.length?jobs.map(job=>`<button type="button" class="document-service-task ${selected?.id===job.id?'active':''}" data-doc-translation-open="${esc(job.id)}"><span>${icon('file',18)}<b>${esc(job.fileName||'文档翻译')}</b><small>${esc(languageNames[job.sourceLanguage]||job.sourceLanguage||'')} → ${esc(languageNames[job.targetLanguage]||job.targetLanguage||'')}</small></span><em class="${job.status==='completed'?'is-success':''}">${esc(statusNames[job.status]||'处理中')} →</em></button>`).join(''):'<p class="document-service-empty">提交后，翻译进度和可下载结果会保留在这里。</p>';node.querySelectorAll('[data-doc-translation-open]').forEach(button=>button.onclick=()=>{if(!busy)void openJob(button.dataset.docTranslationOpen);});}
 function renderSelected(){if(!selected||!current())return;const job=selected,result=job.result,artifacts=Array.isArray(result?.artifacts)?result.artifacts:[];const output=$('[data-doc-translation-detail]');output.innerHTML=`<article class="document-service-result"><header><div><span>${job.status==='completed'?'翻译已完成':'文档翻译进度'}</span><h4>${esc(job.fileName||'文档翻译')}</h4></div><b class="${job.status==='completed'?'is-success':''}">${esc(statusNames[job.status]||'处理中')}</b></header><p>${esc(languageNames[job.sourceLanguage]||job.sourceLanguage)} → ${esc(languageNames[job.targetLanguage]||job.targetLanguage)}${Number(job.pageCount||result?.pageCount)?' · '+Number(job.pageCount||result.pageCount)+' 页':''}</p>${job.status==='failed'?`<p class="is-error" role="alert">${esc(typeof job.error==='string'?job.error:job.error?.message||'翻译未完成，请稍后重试或更换文档。')}</p>`:job.status==='cancelled'?'<p>本站任务已停止，上游可能仍在处理。原件保留在账户中。</p>':!terminal(job.status)?'<p>文档正在云端处理。你可以离开，稍后回到“文献翻译”查看，不需要重复上传。</p>':'<p>下载后请核对专业术语、数字、图表、公式与排版。</p>'}<div class="document-service-actions">${artifacts.map(file=>{const path=translationDownloadPath(file.downloadUrl);return path?`<a class="btn primary" href="${esc(path)}">${icon('download',16)} 下载译文 Word</a>`:'';}).join('')}${!terminal(job.status)?'<button type="button" class="btn secondary" data-doc-translation-cancel>取消本站任务</button>':''}</div>${Array.isArray(result?.warnings)&&result.warnings.length?`<ul>${result.warnings.map(w=>`<li>${esc(w)}</li>`).join('')}</ul>`:''}</article>`;const cancel=$('[data-doc-translation-cancel]');if(cancel)cancel.onclick=async()=>{cancel.disabled=true;try{await client.request('/document-translations/'+encodeURIComponent(job.id)+'/cancel',{});await openJob(job.id);}catch(error){if(current()&&error.name!=='AbortError'){state(error.message,true);cancel.disabled=false;}}};}
 function schedule(){clearTimeout(timer);if(selected&&!terminal(selected.status)&&current())timer=setTimeout(()=>void openJob(selected.id,true),pollInterval);}
 async function openJob(id,poll=false){clearTimeout(timer);const ticket=++operation;try{const job=await client.request('/document-translations/'+encodeURIComponent(id));if(!current()||ticket!==operation)return;selected=job;jobs=[job,...jobs.filter(item=>item.id!==job.id)].slice(0,20);renderJobs();renderSelected();if(!poll)state('已读取任务进度。');schedule();}catch(error){if(current()&&ticket===operation&&error.name!=='AbortError'){state(error.status===401?'登录已失效，请重新登录后查看任务。':error.message,true);if(poll&&error.status!==401)timer=setTimeout(()=>void openJob(id,true),pollInterval*2);}}}
 async function refresh(){if(busy||!current())return;setBusy(true);try{const value=await client.request('/document-translations');jobs=Array.isArray(value.items)?value.items:[];renderJobs();state('任务列表已更新。');if(selected)await openJob(selected.id);}catch(error){if(current()&&error.name!=='AbortError')state(error.message,true);}finally{if(current())setBusy(false);}}
 async function submit(){if(busy)return;const accountFile=$('[data-doc-file]').value,file=$('[data-doc-upload]').files?.[0],sourceLanguage=$('[data-doc-source]').value,targetLanguage=$('[data-doc-target]').value;if(sourceLanguage===targetLanguage)return state('原文语言与目标语言不能相同。',true);if(!$('[data-doc-consent]').checked)return state('请先确认文档处理授权与云端处理说明。',true);try{if(!accountFile)validateTranslationFile(file,cap);else{const existing=files.find(row=>row.id===accountFile);if(!existing)throw Error('所选原件已不存在，请刷新后重试。');validateTranslationFile({name:existing.name,size:Number(existing.bytes)},cap);}}catch(error){return state(error.message,true);}setBusy(true);clearTimeout(timer);try{const latest=await client.request('/auth/me');if(latest.user?.id!==session.user.id)throw Error('登录账户已变化，请关闭窗口后重新打开。');let fileId=accountFile;if(!fileId){state(uploaded?'正在恢复已上传原件…':'正在上传原件到你的账户…');if(!uploaded){const saved=await client.request('/files',{name:file.name,data:await fileBase64(file),expectedUserId:session.user.id},{timeout:120000});if(!saved.id)throw Error('原件上传未返回编号，请先在我的项目核对。');uploaded=saved.id;files.unshift({...saved,name:file.name,bytes:file.size});}fileId=uploaded;}state('原件已保存，正在提交翻译…');const job=await client.request('/document-translations',{fileId,sourceLanguage,targetLanguage,idempotencyKey:requestKey,consent:true,expectedUserId:session.user.id},{timeout:60000});if(!job.id)throw Error('未取得任务编号，请刷新任务列表核对，无需重复提交。');requestKey=uuid();await openJob(job.id);notify('文档翻译已提交，可在此查看进度。');}catch(error){if(current()&&error.name!=='AbortError')state(error.message,true);}finally{if(current()){setBusy(false);schedule();}}}
 const ready=(async()=>{container.innerHTML='<p class="document-service-loading" role="status">正在读取账户与文档翻译服务…</p>';try{const [me,capabilities]=await Promise.all([client.request('/auth/me'),client.request('/capabilities')]);session=me;cap=capabilities.documentTranslation||{};if(!me.user?.id){container.innerHTML=`<div class="document-service-empty"><h3>登录后翻译整篇文档</h3><p>原件与译文按账户私有保存，任务可稍后继续查看。</p><a class="btn primary" href="${esc(documentServiceLoginHref())}">登录账户 →</a></div>`;return;}if(!cap.ready){container.innerHTML='<div class="document-service-empty"><h3>整篇文档翻译暂未开放</h3><p>请稍后重试。你仍可使用“原文对照翻译”处理已导入的文本。</p></div>';return;}const [fileList,jobList]=await Promise.all([client.request('/files'),client.request('/document-translations')]);files=eligibleTranslationFiles(fileList.items);jobs=Array.isArray(jobList.items)?jobList.items:[];render();const active=jobs.find(job=>!terminal(job.status));if(active)await openJob(active.id);}catch(error){if(current()&&error.name!=='AbortError')container.innerHTML=`<div class="document-service-empty"><p role="alert">${esc(error.status===401?'请登录后再使用整篇文档翻译。':error.message)}</p>${error.status===401?`<a class="btn primary" href="${esc(documentServiceLoginHref())}">登录账户 →</a>`:''}</div>`;}})();
 return {ready,dispose};
}
